CREATE TABLE IF NOT EXISTS production_release_attempts (version_id TEXT NOT NULL CHECK (length(trim(version_id)) > 0), candidate_commit TEXT NOT NULL CHECK (length(trim(candidate_commit)) > 0), manifest_checksum TEXT NOT NULL CHECK (length(trim(manifest_checksum)) > 0), attempt INTEGER NOT NULL CHECK (attempt > 0), idempotency_key TEXT NOT NULL UNIQUE CHECK (length(trim(idempotency_key)) > 0), status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed')), started_at TEXT NOT NULL CHECK (length(trim(started_at)) > 0), completed_at TEXT CHECK (completed_at IS NULL OR length(trim(completed_at)) > 0), created_at TEXT NOT NULL CHECK (length(trim(created_at)) > 0), updated_at TEXT NOT NULL CHECK (length(trim(updated_at)) > 0), failure_fingerprint TEXT CHECK (failure_fingerprint IS NULL OR length(trim(failure_fingerprint)) > 0), PRIMARY KEY (version_id, candidate_commit, manifest_checksum, attempt), CHECK ((status IN ('pending', 'running') AND completed_at IS NULL AND failure_fingerprint IS NULL) OR (status = 'succeeded' AND completed_at IS NOT NULL AND failure_fingerprint IS NULL) OR (status = 'failed' AND completed_at IS NOT NULL AND failure_fingerprint IS NOT NULL)));
CREATE TABLE IF NOT EXISTS production_release_targets (version_id TEXT NOT NULL CHECK (length(trim(version_id)) > 0), candidate_commit TEXT NOT NULL CHECK (length(trim(candidate_commit)) > 0), manifest_checksum TEXT NOT NULL CHECK (length(trim(manifest_checksum)) > 0), platform TEXT NOT NULL CHECK (platform IN ('web', 'api', 'ios')), app_id TEXT NOT NULL, attempt INTEGER NOT NULL CHECK (attempt > 0), stage TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed')), external_request_id TEXT CHECK (external_request_id IS NULL OR length(trim(external_request_id)) > 0), reconciliation_status TEXT NOT NULL DEFAULT 'not_required' CHECK (reconciliation_status IN ('not_required', 'pending_readback', 'unknown_outcome', 'readback_confirmed', 'readback_mismatch')), failure_classification TEXT CHECK (failure_classification IS NULL OR failure_classification IN ('product_rework', 'release_infrastructure', 'external_unknown', 'validation')), sanitized_error_summary TEXT CHECK (sanitized_error_summary IS NULL OR (length(trim(sanitized_error_summary)) > 0 AND length(sanitized_error_summary) <= 1024)), artifact_identity TEXT CHECK (artifact_identity IS NULL OR length(trim(artifact_identity)) > 0), production_readback_sha TEXT CHECK (production_readback_sha IS NULL OR length(trim(production_readback_sha)) > 0), production_release_id TEXT CHECK (production_release_id IS NULL OR length(trim(production_release_id)) > 0), health_status TEXT CHECK (health_status IS NULL OR health_status IN ('unknown', 'healthy', 'unhealthy')), readback_status TEXT CHECK (readback_status IS NULL OR readback_status IN ('unknown', 'confirmed', 'mismatch')), app_store_app_id TEXT CHECK (app_store_app_id IS NULL OR length(trim(app_store_app_id)) > 0), bundle_id TEXT CHECK (bundle_id IS NULL OR length(trim(bundle_id)) > 0), marketing_version TEXT CHECK (marketing_version IS NULL OR length(trim(marketing_version)) > 0), build_number TEXT CHECK (build_number IS NULL OR length(trim(build_number)) > 0), processing_status TEXT CHECK (processing_status IS NULL OR processing_status IN ('queued', 'processing', 'processed', 'failed')), processing_id TEXT CHECK (processing_id IS NULL OR length(trim(processing_id)) > 0), review_status TEXT CHECK (review_status IS NULL OR review_status IN ('not_submitted', 'submitted', 'approved', 'rejected')), review_submission_id TEXT CHECK (review_submission_id IS NULL OR length(trim(review_submission_id)) > 0), upload_id TEXT CHECK (upload_id IS NULL OR length(trim(upload_id)) > 0), review_id TEXT CHECK (review_id IS NULL OR length(trim(review_id)) > 0), release_status TEXT CHECK (release_status IS NULL OR release_status IN ('not_released', 'released', 'failed')), release_id TEXT CHECK (release_id IS NULL OR length(trim(release_id)) > 0), live_status TEXT CHECK (live_status IS NULL OR live_status IN ('not_live', 'live', 'failed')), live_id TEXT CHECK (live_id IS NULL OR length(trim(live_id)) > 0), live_marketing_version TEXT CHECK (live_marketing_version IS NULL OR length(trim(live_marketing_version)) > 0), live_build_number TEXT CHECK (live_build_number IS NULL OR length(trim(live_build_number)) > 0), live_membership_confirmed INTEGER CHECK (live_membership_confirmed IS NULL OR live_membership_confirmed IN (0, 1)), sanitized_observed_evidence TEXT CHECK (sanitized_observed_evidence IS NULL OR (length(trim(sanitized_observed_evidence)) > 0 AND length(sanitized_observed_evidence) <= 4096 AND json_valid(sanitized_observed_evidence))), sanitized_readback_evidence TEXT CHECK (sanitized_readback_evidence IS NULL OR (length(trim(sanitized_readback_evidence)) > 0 AND length(sanitized_readback_evidence) <= 4096 AND json_valid(sanitized_readback_evidence))), sanitized_live_evidence TEXT CHECK (sanitized_live_evidence IS NULL OR (length(trim(sanitized_live_evidence)) > 0 AND length(sanitized_live_evidence) <= 4096 AND json_valid(sanitized_live_evidence))), failure_fingerprint TEXT CHECK (failure_fingerprint IS NULL OR length(trim(failure_fingerprint)) > 0), started_at TEXT NOT NULL CHECK (length(trim(started_at)) > 0), completed_at TEXT CHECK (completed_at IS NULL OR length(trim(completed_at)) > 0), created_at TEXT NOT NULL CHECK (length(trim(created_at)) > 0), updated_at TEXT NOT NULL CHECK (length(trim(updated_at)) > 0), PRIMARY KEY (version_id, candidate_commit, manifest_checksum, platform, app_id, attempt), CHECK ((platform IN ('web', 'api') AND app_id = '' AND stage IN ('preflight', 'upload', 'switch', 'health', 'readback')) OR (platform = 'ios' AND length(trim(app_id)) > 0 AND stage IN ('test', 'archive', 'upload', 'processing', 'review_submit', 'review_wait', 'release', 'live_readback') AND app_store_app_id IS NOT NULL AND length(trim(app_store_app_id)) > 0 AND bundle_id IS NOT NULL AND length(trim(bundle_id)) > 0 AND marketing_version IS NOT NULL AND length(trim(marketing_version)) > 0 AND (stage IN ('test', 'archive') OR (build_number IS NOT NULL AND length(trim(build_number)) > 0)))), CHECK (status <> 'succeeded' OR ((platform IN ('web', 'api') AND stage = 'readback') OR (platform = 'ios' AND stage = 'live_readback'))), CHECK (NOT (status = 'succeeded' AND platform IN ('web', 'api') AND stage = 'readback') OR (reconciliation_status IN ('not_required', 'readback_confirmed') AND completed_at IS NOT NULL AND length(trim(completed_at)) > 0 AND external_request_id IS NOT NULL AND length(trim(external_request_id)) > 0 AND artifact_identity IS NOT NULL AND length(trim(artifact_identity)) > 0 AND production_readback_sha IS NOT NULL AND length(trim(production_readback_sha)) > 0 AND production_readback_sha = candidate_commit AND production_release_id IS NOT NULL AND length(trim(production_release_id)) > 0 AND health_status = 'healthy' AND readback_status = 'confirmed' AND sanitized_observed_evidence IS NOT NULL AND length(trim(sanitized_observed_evidence)) > 0 AND sanitized_readback_evidence IS NOT NULL AND length(trim(sanitized_readback_evidence)) > 0)), CHECK (NOT (status = 'succeeded' AND platform = 'ios' AND stage = 'live_readback') OR (reconciliation_status IN ('not_required', 'readback_confirmed') AND completed_at IS NOT NULL AND length(trim(completed_at)) > 0 AND external_request_id IS NOT NULL AND length(trim(external_request_id)) > 0 AND app_store_app_id IS NOT NULL AND length(trim(app_store_app_id)) > 0 AND bundle_id IS NOT NULL AND length(trim(bundle_id)) > 0 AND marketing_version IS NOT NULL AND length(trim(marketing_version)) > 0 AND build_number IS NOT NULL AND length(trim(build_number)) > 0 AND upload_id IS NOT NULL AND length(trim(upload_id)) > 0 AND processing_status = 'processed' AND processing_id IS NOT NULL AND length(trim(processing_id)) > 0 AND review_status = 'approved' AND review_submission_id IS NOT NULL AND length(trim(review_submission_id)) > 0 AND review_id IS NOT NULL AND length(trim(review_id)) > 0 AND release_status = 'released' AND release_id IS NOT NULL AND length(trim(release_id)) > 0 AND live_status = 'live' AND live_id IS NOT NULL AND length(trim(live_id)) > 0 AND live_marketing_version IS NOT NULL AND live_marketing_version = marketing_version AND live_build_number IS NOT NULL AND live_build_number = build_number AND (live_membership_confirmed = 1 OR (sanitized_live_evidence IS NOT NULL AND length(trim(sanitized_live_evidence)) > 0)) AND sanitized_observed_evidence IS NOT NULL AND length(trim(sanitized_observed_evidence)) > 0)));
CREATE INDEX IF NOT EXISTS idx_production_release_targets_latest ON production_release_targets (version_id, candidate_commit, manifest_checksum, platform, app_id, attempt DESC);
CREATE INDEX IF NOT EXISTS idx_production_release_targets_reusable_success ON production_release_targets (version_id, candidate_commit, manifest_checksum, platform, app_id, attempt DESC) WHERE status = 'succeeded' AND reconciliation_status IN ('not_required', 'readback_confirmed') AND ((platform IN ('web', 'api') AND stage = 'readback' AND completed_at IS NOT NULL AND external_request_id IS NOT NULL AND artifact_identity IS NOT NULL AND production_readback_sha IS NOT NULL AND production_readback_sha = candidate_commit AND production_release_id IS NOT NULL AND health_status = 'healthy' AND readback_status = 'confirmed' AND sanitized_observed_evidence IS NOT NULL AND sanitized_readback_evidence IS NOT NULL) OR (platform = 'ios' AND stage = 'live_readback' AND completed_at IS NOT NULL AND external_request_id IS NOT NULL AND app_store_app_id IS NOT NULL AND bundle_id IS NOT NULL AND marketing_version IS NOT NULL AND build_number IS NOT NULL AND upload_id IS NOT NULL AND processing_status = 'processed' AND processing_id IS NOT NULL AND review_status = 'approved' AND review_submission_id IS NOT NULL AND review_id IS NOT NULL AND release_status = 'released' AND release_id IS NOT NULL AND live_status = 'live' AND live_id IS NOT NULL AND live_marketing_version = marketing_version AND live_build_number = build_number AND sanitized_observed_evidence IS NOT NULL AND (live_membership_confirmed = 1 OR sanitized_live_evidence IS NOT NULL)));
CREATE TRIGGER IF NOT EXISTS production_release_attempts_immutable_succeeded BEFORE UPDATE ON production_release_attempts WHEN OLD.status = 'succeeded' BEGIN SELECT RAISE(ABORT, 'immutable succeeded production release attempt'); END;
CREATE TRIGGER IF NOT EXISTS production_release_targets_immutable_succeeded BEFORE UPDATE ON production_release_targets WHEN OLD.status = 'succeeded' BEGIN SELECT RAISE(ABORT, 'immutable succeeded production release target'); END;
CREATE TRIGGER IF NOT EXISTS production_release_attempts_immutable_succeeded_delete BEFORE DELETE ON production_release_attempts WHEN OLD.status = 'succeeded' BEGIN SELECT RAISE(ABORT, 'immutable succeeded production release attempt'); END;
CREATE TRIGGER IF NOT EXISTS production_release_targets_immutable_succeeded_delete BEFORE DELETE ON production_release_targets WHEN OLD.status = 'succeeded' BEGIN SELECT RAISE(ABORT, 'immutable succeeded production release target'); END;
